import { useCallback, useMemo, useState } from 'react'

import { useAtomValue } from 'jotai'

import { useStackedTitle } from '@/hooks/useStackedTitle'

import { learnConfigAtom, passRatioAtom } from '../atoms'
import { useGithubToken } from '../hooks'
import type { FlashCardItem } from '../types'
import { shuffleArray } from '../utils'

import { useAddHistory } from './useAddHistory'
import { useFlashCardContentSuspense } from './useFlashCardContent'
import { useLearningHistorySummary } from './useLearningHistorySummary'

export function useFlashCardQuiz(params: { owner?: string; repo?: string; path?: string }) {
  const { owner, repo, path } = params
  const token = useGithubToken()
  const { shuffle, qaDirection } = useAtomValue(learnConfigAtom)
  const passRatio = useAtomValue(passRatioAtom)

  const { content } = useFlashCardContentSuspense(params)

  const contentInfo = useMemo(() => {
    if (!content || !owner || !repo || !path || !content.sha) return null
    return { owner, repo, path, sha: content.sha }
  }, [content, owner, repo, path])

  const {
    addResult: addHistoryResult,
    completeSession,
    retrySave,
    saveState,
    getDuration,
    resetDuration,
  } = useAddHistory(contentInfo)

  const [currentIndex, setCurrentIndex] = useState(0)
  const [results, setResults] = useState<Map<number, 'pass' | 'fail'>>(new Map())
  const [isComplete, setIsComplete] = useState(false)
  // 완료 시점에 확정되는 총 소요 시간. 진행 중 표시는 QuizProgressBar가
  // getDuration으로 자체 tick한다 (매초 뷰 전체 리렌더링 방지).
  const [elapsedSeconds, setElapsedSeconds] = useState(0)

  const summary = useLearningHistorySummary(content?.sha)

  const contentFlashCardItems = content?.flashCardItems
  const flashCardItems = useMemo<FlashCardItem[]>(() => {
    if (!contentFlashCardItems) return []

    // Build per-item pass ratio map
    const lineHistories = new Map<number, { pass: number; total: number }>()
    for (const h of summary.histories) {
      if (h.type === 'fin') continue
      const entry = lineHistories.get(h.line_no) ?? { pass: 0, total: 0 }
      entry.total++
      if (h.type === 'pass') entry.pass++
      lineHistories.set(h.line_no, entry)
    }

    // Filter by passRatio threshold
    const filtered = contentFlashCardItems.filter((item) => {
      const entry = lineHistories.get(item.lineNo)
      const ratio = entry && entry.total > 0 ? (entry.pass / entry.total) * 100 : 0
      return ratio <= passRatio
    })
    // console.log({ passRatio, filtered })

    const items =
      qaDirection === 'reverse'
        ? filtered.map((item) => ({ ...item, q: item.a, a: item.q }))
        : filtered
    return shuffle ? shuffleArray(items) : items
  }, [contentFlashCardItems, qaDirection, shuffle, passRatio, summary.histories])

  const currentItem = flashCardItems[currentIndex]
  const total = flashCardItems.length
  const passCount = Array.from(results.values()).filter((r) => r === 'pass').length
  const failCount = Array.from(results.values()).filter((r) => r === 'fail').length
  const progress = total > 0 ? ((passCount + failCount) / total) * 100 : 0

  const failedItems = useMemo(() => {
    return flashCardItems.filter((_, index) => results.get(index) === 'fail')
  }, [flashCardItems, results])

  const recordResult = useCallback(
    (result: 'pass' | 'fail') => {
      setResults((prev) => new Map(prev).set(currentIndex, result))
      if (currentItem) {
        addHistoryResult(result, currentItem.lineNo)
      }
    },
    [currentIndex, currentItem, addHistoryResult]
  )

  const advance = useCallback(async () => {
    if (currentIndex < total - 1) {
      setCurrentIndex((prev) => prev + 1)
    } else {
      setElapsedSeconds(Math.round(getDuration() / 1000))
      setIsComplete(true)
      // 저장이 끝날 때까지 기다린다. 그동안 완료 화면의 이동 버튼은 saveState로 잠근다.
      await completeSession()
    }
  }, [currentIndex, total, completeSession, getDuration])

  const restart = useCallback(() => {
    setCurrentIndex(0)
    setResults(new Map())
    setIsComplete(false)
    setElapsedSeconds(0)
    resetDuration()
  }, [resetDuration])

  useStackedTitle(content?.name)

  return {
    content,
    token,
    flashCardItems,
    currentIndex,
    currentItem,
    total,
    passCount,
    failCount,
    failedItems,
    progress,
    isComplete,
    elapsedSeconds,
    getDuration,
    recordResult,
    advance,
    restart,
    saveState,
    retrySave,
  }
}
