import { memo, useCallback, useMemo, useRef, useState } from 'react'

import { useAtom } from 'jotai'
import debounce from 'lodash-es/debounce'
import { RgbaStringColorPicker } from 'react-colorful'
import { ReactSketchCanvas, type ReactSketchCanvasRef } from 'react-sketch-canvas'

import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown'
import CancelIcon from '@mui/icons-material/Cancel'
import DeleteIcon from '@mui/icons-material/Delete'
import DrawIcon from '@mui/icons-material/Draw'
import PaletteIcon from '@mui/icons-material/Palette'
import type { BoxProps } from '@mui/material'
import {
  Box,
  Button,
  ButtonGroup,
  Divider,
  IconButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
} from '@mui/material'

import { atomWithStorageForSpa } from '@/atoms/utils-atom'

import { learnConfigAtom } from '../atoms'
import type { FlashCardNoteTarget } from '../hooks/useFlashCardNotes'
import { formatCardSourcePath } from '../utils'

import CopyPromptButton from './CopyPromptButton'
import { HintButton } from './HintButton'
import { QuizNoteButton } from './QuizNoteButton'

export type DrawPadProps = {
  className?: string
  question: string
  answer: string
  scrollPadding?: boolean
  noteTarget?: FlashCardNoteTarget | null
} & Pick<BoxProps, 'sx'>

type DrawPadConfig = {
  colorHistories?: string[]
}

const DEFAULT_COLOR = 'rgba(255, 0, 0, .7)'

/** 메뉴에서 한 번에 고를 수 있는 프리셋 색. 첫 항목은 DEFAULT_COLOR와 같다. */
const PRESET_COLORS = [
  DEFAULT_COLOR,
  'rgba(255, 152, 0, .7)',
  'rgba(255, 235, 59, .7)',
  'rgba(76, 175, 80, .7)',
  'rgba(33, 150, 243, .7)',
  'rgba(156, 39, 176, .7)',
  'rgba(255, 255, 255, .7)',
  'rgba(0, 0, 0, .7)',
]

export const CONTROL_AREA = '36px'

const drawPadConfigAtom = atomWithStorageForSpa<DrawPadConfig>('drawPadConfig', {
  colorHistories: [],
})

function DrawPad(props: DrawPadProps) {
  const { className, sx, question, answer, scrollPadding, noteTarget } = props
  const [{ colorHistories = [] }, setDrawPadConfig] = useAtom(drawPadConfigAtom)
  // 그리기 on/off는 학습 설정(learnConfig.drawPad)과 같은 값을 공유한다.
  // 캔버스가 켜져 있으면 touch-action: none 때문에 아래 문제 영역을 스크롤할 수 없으므로,
  // 학습 중에도 컨트롤 바에서 바로 끄고 켤 수 있게 한다.
  const [{ drawPad: drawingEnabled = true }, setLearnConfig] = useAtom(learnConfigAtom)
  const activeColor = colorHistories[0] || DEFAULT_COLOR
  const refCanvasDraw = useRef<ReactSketchCanvasRef>(null)
  // Menu anchor는 렌더 중 읽어야 하므로 ref 대신 state로 보관한다.
  const [anchorEl, setAnchorEl] = useState<HTMLDivElement | null>(null)

  const [showColorPicker, setShowColorPicker] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)

  const closeMenu = useCallback(() => setMenuOpen(false), [])

  const toggleDrawing = useCallback(() => {
    setLearnConfig((prev) => ({ ...prev, drawPad: !(prev.drawPad ?? true) }))
    setShowColorPicker(false)
    setMenuOpen(false)
  }, [setLearnConfig])

  // inline 객체로 넘기면 HintButton(과 열린 힌트 Dialog)이 렌더마다 리렌더링되므로
  // identity를 고정한다.
  const hintTarget = useMemo(
    () =>
      noteTarget
        ? {
            owner: noteTarget.owner,
            repo: noteTarget.repo,
            path: noteTarget.path,
            itemId: noteTarget.itemId,
            q: question,
            a: answer,
          }
        : null,
    [noteTarget, question, answer]
  )

  const setActiveColor = useCallback(
    (color: string) => {
      setDrawPadConfig((prev) => {
        const { colorHistories = [] } = prev
        const colorHistoriesNext = colorHistories.slice(0)
        colorHistoriesNext[0] = color
        return {
          ...prev,
          colorHistories: colorHistoriesNext,
        }
      })
    },
    [setDrawPadConfig]
  )

  const handleChangeColor = useMemo(() => debounce(setActiveColor, 300), [setActiveColor])

  const handleSelectPreset = useCallback(
    (color: string) => {
      setActiveColor(color)
      closeMenu()
    },
    [setActiveColor, closeMenu]
  )

  const handleOpenCustomColor = useCallback(() => {
    closeMenu()
    setShowColorPicker(true)
  }, [closeMenu])

  const handleClear = useCallback(() => {
    closeMenu()
    refCanvasDraw.current?.clearCanvas()
  }, [closeMenu])

  // console.log('DrawPad')
  return (
    <Box
      className={className}
      // 캔버스가 꺼져 있으면 오버레이가 포인터를 삼키지 않게 해 아래 문제 영역을
      // 스크롤·선택할 수 있게 한다. 컨트롤 바는 pointerEvents: 'auto'라 그대로 동작한다.
      // 캔버스가 켜져 있으면 모바일 long-press가 아래 텍스트를 선택하거나 콜아웃을 띄우지
      // 않도록 선택·콜아웃·contextmenu를 막는다. React 17+는 touchstart를 passive로 붙여서
      // preventDefault로는 못 막고 CSS로만 가능하다.
      onContextMenu={drawingEnabled ? (e) => e.preventDefault() : undefined}
      sx={{
        width: '100%',
        position: 'relative',
        pointerEvents: drawingEnabled ? undefined : 'none',
        ...(drawingEnabled && {
          userSelect: 'none',
          WebkitUserSelect: 'none',
          WebkitTouchCallout: 'none',
        }),
        ...sx,
      }}
    >
      {drawingEnabled && (
        <ReactSketchCanvas
          ref={refCanvasDraw}
          style={{ width: '100%', height: '100%', border: 'none' }}
          canvasColor="transparent"
          strokeColor={activeColor}
          strokeWidth={2}
        />
      )}
      <Box
        sx={{
          position: 'absolute',
          top: '0',
          display: 'flex',
          width: '100%',
          justifyContent: 'space-between',
          pointerEvents: 'none',
        }}
      >
        <Box sx={{ display: 'flex', pointerEvents: 'auto' }}>
          <ButtonGroup ref={setAnchorEl} variant="outlined" size="small">
            <Button
              sx={{
                fontSize: '1rem',
                minWidth: 0,
                px: 1.5,
                // 켜짐 = 현재 펜 색으로 테두리·아이콘, 꺼짐 = 흐린 아이콘
                ...(drawingEnabled && {
                  borderColor: activeColor,
                  '&:hover': { borderColor: activeColor },
                }),
              }}
              onClick={toggleDrawing}
              aria-pressed={drawingEnabled}
              aria-label="그리기 패드"
            >
              <DrawIcon
                fontSize="small"
                sx={{ color: drawingEnabled ? activeColor : 'text.disabled' }}
              />
            </Button>
            {drawingEnabled && (
              <Button
                sx={{ minWidth: 0, px: 0.25 }}
                onClick={() => setMenuOpen(true)}
                aria-haspopup="menu"
                aria-expanded={menuOpen}
                aria-label="그리기 옵션"
              >
                <ArrowDropDownIcon fontSize="small" />
              </Button>
            )}
          </ButtonGroup>
          <Menu
            anchorEl={anchorEl}
            open={menuOpen}
            onClose={closeMenu}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
            transformOrigin={{ vertical: 'top', horizontal: 'left' }}
          >
            <Box sx={{ display: 'flex', gap: 0.75, px: 1.5, py: 0.5 }}>
              {PRESET_COLORS.map((color) => {
                const selected = color === activeColor
                return (
                  <Box
                    key={color}
                    role="menuitemradio"
                    aria-checked={selected}
                    aria-label={color}
                    tabIndex={0}
                    onClick={() => handleSelectPreset(color)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault()
                        handleSelectPreset(color)
                      }
                    }}
                    sx={{
                      width: 24,
                      height: 24,
                      borderRadius: '50%',
                      backgroundColor: color,
                      cursor: 'pointer',
                      border: selected ? '2px solid' : '1px solid',
                      borderColor: selected ? 'primary.main' : 'divider',
                      boxSizing: 'border-box',
                    }}
                  />
                )
              })}
            </Box>
            <Divider />
            <MenuItem onClick={handleOpenCustomColor}>
              <ListItemIcon>
                <PaletteIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>사용자 지정 색…</ListItemText>
            </MenuItem>
            <MenuItem onClick={handleClear}>
              <ListItemIcon>
                <DeleteIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>전체 지우기</ListItemText>
            </MenuItem>
          </Menu>
        </Box>
        <Box sx={{ display: 'flex', pointerEvents: 'auto', gap: '.2rem' }}>
          <HintButton target={hintTarget} />
          {noteTarget !== undefined && <QuizNoteButton target={noteTarget} />}
          <CopyPromptButton
            q={question}
            a={answer}
            itemId={noteTarget?.itemId}
            sourcePath={formatCardSourcePath(noteTarget?.owner, noteTarget?.repo, noteTarget?.path)}
          />
        </Box>
      </Box>
      {drawingEnabled && showColorPicker && (
        <Box
          sx={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 1300,
          }}
        >
          <Box sx={{ textAlign: 'right' }}>
            <IconButton onClick={() => setShowColorPicker(false)}>
              <CancelIcon />
            </IconButton>
          </Box>
          <RgbaStringColorPicker
            color={activeColor}
            onChange={(color) => handleChangeColor(color)}
          />
        </Box>
      )}
      {scrollPadding && (
        <Box
          sx={{
            position: 'absolute',
            top: 0,
            right: 0,
            width: '2rem',
            height: '100%',
          }}
        />
      )}
    </Box>
  )
}

export default memo(DrawPad)
