import { useCallback } from 'react'

import { useBeforeUnload, useBlocker } from 'react-router-dom'

import Button from '@mui/material/Button'
import Dialog from '@mui/material/Dialog'
import DialogActions from '@mui/material/DialogActions'
import DialogContent from '@mui/material/DialogContent'
import DialogContentText from '@mui/material/DialogContentText'
import DialogTitle from '@mui/material/DialogTitle'

type LearnBlockerProps = {
  /** true인 동안 이탈을 막는다. 학습이 끝나면 false로 내려 자연스럽게 이동할 수 있게 한다. */
  when: boolean
}

/**
 * 학습 중 이탈 방지.
 *
 * - 라우터 이동(브라우저 뒤로/앞으로, 앱 내 navigate/Link)은 `useBlocker`로 잡아 확인 다이얼로그를 띄운다.
 *   data router(createHashRouter/createMemoryRouter)에서만 동작한다.
 * - 새로고침·탭 닫기·URL 직접 입력은 `beforeunload`로 브라우저 기본 확인창만 띄울 수 있다
 *   (커스텀 UI 불가, iOS Safari는 이벤트 자체가 없음).
 */
function LearnBlocker({ when }: LearnBlockerProps) {
  const blocker = useBlocker(when)

  useBeforeUnload(
    useCallback(
      (e: BeforeUnloadEvent) => {
        if (!when) return
        e.preventDefault()
        // Chrome/Edge는 returnValue가 설정돼야 확인창을 띄운다. 문구는 브라우저가 무시한다.
        e.returnValue = ''
      },
      [when]
    )
  )

  if (blocker.state !== 'blocked') return null

  return (
    <Dialog open onClose={() => blocker.reset()}>
      <DialogTitle>학습을 종료할까요?</DialogTitle>
      <DialogContent>
        <DialogContentText>지금 나가면 현재 학습 진행 상황이 저장되지 않습니다.</DialogContentText>
      </DialogContent>
      <DialogActions>
        <Button onClick={() => blocker.reset()}>계속 학습</Button>
        <Button onClick={() => blocker.proceed()} color="error">
          나가기
        </Button>
      </DialogActions>
    </Dialog>
  )
}

export default LearnBlocker
